<?php
require_once __DIR__.'/m0/bootstrap.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/Repository.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/Answers.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/EngineMapper.php';
use EIPSI\AssessmentEditor\Definition as D;
use EIPSI\AssessmentEditor\Repository as R;
use EIPSI\AssessmentEditor\Answers as A;
use EIPSI\AssessmentEditor\RichText as H;
use EIPSI\AssessmentEditor\EngineMapper as M;
$tests=0;$failures=0;$owned=array();
function cr_test($name,$fn){global $tests,$failures;$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failures++;echo "FAIL $name: ".$e->getMessage()."\n";}}
function cr_assert($v,$m='Assertion failed'){if(!$v)throw new RuntimeException($m);}
function cr_reject($fn){try{$fn();}catch(Throwable $e){return;}throw new RuntimeException('Expected rejection');}
function cr_fixture(){return D::validate(json_decode(file_get_contents(__DIR__.'/assessment-editor/corrections-fixture.json'),true));}
function cr_one($t){$d=cr_fixture();$d['elements']=array_values(array_filter($d['elements'],static function($e)use($t){return $e['type']===$t;}));return $d;}
function cr_derive(&$e){foreach($e['properties']['matrix_rows'] as $i=>&$r)$r['variable_name']=$e['properties']['variable_name'].'_'.($i+1);unset($r);}
wp_set_current_user(1);
try{
cr_test('corrected maximal fixture is canonical including allocator and derived names',function(){$d=cr_fixture();cr_assert(D::json(D::validate($d))===D::json($d));});
cr_test('all prior fixtures load with stable technical IDs keys and idempotent defaults',function(){foreach(array('fixture.json','parity-fixture.json','authoring-fixture.json') as $file){$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/'.$file),true);$before=D::json($d);$n=D::validate($d);cr_assert(D::json($d)===$before);cr_assert(D::json(D::validate($n))===D::json($n));foreach($d['elements'] as $i=>$e){cr_assert($n['elements'][$i]['id']===$e['id']);cr_assert($n['elements'][$i]['response_key']===$e['response_key']);}}});
cr_test('missing legacy Text variables receive ordered family defaults and preserve manual names',function(){$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/parity-fixture.json'),true);$n=D::validate($d);$names=array();foreach($n['elements'] as $e)if(in_array($e['type'],array('text','textarea','email','number','tel','url'),true))$names[]=$e['properties']['variable_name'];cr_assert($names===array('text_1','text_2','text_3','text_4','text_5','text_6'));$d['elements'][0]['properties']['variable_name']='ansiedad';cr_assert(D::validate($d)['elements'][0]['properties']['variable_name']==='ansiedad');});
cr_test('allocator resumes historical ordinal when a new name is absent',function(){$d=cr_one('text');$d['authoring']['variable_next']['text']=10;unset($d['elements'][0]['properties']['variable_name']);$n=D::validate($d);cr_assert($n['elements'][0]['properties']['variable_name']==='text_10');cr_assert($n['authoring']['variable_next']['text']===11);});
cr_test('allocator skips candidate and Matrix derived output conflicts',function(){$d=cr_one('text');$d['elements'][0]['properties']['variable_name']='matrix_1_2';$d['authoring']['variable_next']['matrix']=1;$m=cr_one('matrix')['elements'][0];unset($m['properties']['variable_name']);foreach($m['properties']['matrix_rows'] as &$r)unset($r['variable_name']);unset($r);$d['elements'][]=$m;$n=D::validate($d);cr_assert($n['elements'][1]['properties']['variable_name']==='matrix_2');});
cr_test('counter high water survives save reload deletion and client regression',function()use(&$owned){$d=cr_one('text');$d['id']='AE_'.bin2hex(random_bytes(12));$owned[]=$d['id'];$d['authoring']['variable_next']['text']=20;R::save($d,0);$loaded=R::load($d['id'])['definition'];$loaded['elements']=array();$loaded['authoring']['variable_next']['text']=1;R::save($loaded,1);$again=R::load($d['id'])['definition'];cr_assert($again['authoring']['variable_next']['text']===20);$new=$d['elements'][0];unset($new['properties']['variable_name']);$again['elements'][]=$new;$n=D::validate($again);cr_assert($n['elements'][0]['properties']['variable_name']==='text_20');});
cr_test('allocator metadata rejects negative fractional unknown prefixes and policy',function(){foreach(array(-1,0,1.5,'2') as $v){$d=cr_one('text');$d['authoring']['variable_next']['text']=$v;cr_reject(function()use($d){D::validate($d);});}$d=cr_one('text');$d['authoring']['variable_policy']='wrong';cr_reject(function()use($d){D::validate($d);});});
cr_test('standalone analytical rename and reorder preserve IDs keys and manual variable',function(){$d=cr_fixture();$e=$d['elements'][0];$d['elements'][0]['properties']['variable_name']='ansiedad';$d['elements']=array_reverse($d['elements']);$n=D::validate($d);$last=end($n['elements']);cr_assert($last['id']===$e['id']&&$last['response_key']===$e['response_key']&&$last['properties']['variable_name']==='ansiedad');});
cr_test('standalone duplicate names rejected across nested groups',function(){$d=cr_one('text');$copy=$d['elements'][0];$copy['id']='EL_second';$copy['response_key']='R_second';$d['elements'][]=array('id'=>'GROUP','type'=>'group','response_key'=>null,'properties'=>array('label'=>'Grupo'),'options'=>array(),'children'=>array($copy));cr_reject(function()use($d){D::validate($d);});});
cr_test('same analytical names allowed in independent Assessments and case policy preserved',function()use(&$owned){foreach(array('AE_'.bin2hex(random_bytes(12)),'AE_'.bin2hex(random_bytes(12))) as $id){$d=cr_one('text');$d['id']=$id;$owned[]=$id;$d['elements'][0]['properties']['variable_name']='ansiedad';R::save($d,0);cr_assert(R::load($id)['definition']['elements'][0]['properties']['variable_name']==='ansiedad');}});
cr_test('Matrix base derives ordinal row analytical variables',function(){$d=cr_one('matrix');$e=&$d['elements'][0];$e['properties']['variable_name']='phq';cr_derive($e);$n=D::validate($d);cr_assert(array_column($n['elements'][0]['properties']['matrix_rows'],'variable_name')===array('phq_1','phq_2','phq_3'));});
cr_test('Matrix reorder changes derived suffixes without changing row IDs or response keys',function(){$d=cr_one('matrix');$e=&$d['elements'][0];$before=$e['properties']['matrix_rows'];$e['properties']['matrix_rows']=array_reverse($before);cr_derive($e);$n=D::validate($d);$first=$n['elements'][0]['properties']['matrix_rows'][0];cr_assert($first['id']===$before[2]['id']&&$first['response_key']===$before[2]['response_key']);cr_assert($first['variable_name']==='matrix_1_1');});
cr_test('current policy rejects independently edited or forged row variable names',function(){$d=cr_one('matrix');$d['elements'][0]['properties']['matrix_rows'][0]['variable_name']='independent';cr_reject(function()use($d){D::validate($d);});$d=cr_one('matrix');$d['elements'][0]['properties']['matrix_rows'][0]['variable_override']='bad';cr_reject(function()use($d){D::validate($d);});});
cr_test('legacy independent row names preserved as audit aliases and converted in memory',function(){$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/authoring-fixture.json'),true);$n=D::validate($d);$matrix=end($n['elements']);cr_assert($matrix['properties']['matrix_rows'][0]['variable_name']==='matriz_sintomas_1');cr_assert($n['authoring']['legacy_row_variables'][0]['variable_name']==='sintoma_1');});
cr_test('Matrix derived columns reject standalone collision in same Assessment',function(){$d=cr_one('matrix');$q=cr_one('text')['elements'][0];$q['properties']['variable_name']='matrix_1_2';$d['elements'][]=$q;cr_reject(function()use($d){D::validate($d);});});
cr_test('Matrix base may equal standalone variable while effective outputs remain distinct',function(){$d=cr_one('matrix');$q=cr_one('text')['elements'][0];$q['properties']['variable_name']='matrix_1';$d['elements'][]=$q;D::validate($d);});
cr_test('two Matrices cannot reserve identical derived names',function(){$d=cr_one('matrix');$m=$d['elements'][0];$m['id']='EL_copy';$m['response_key']='R_copy';foreach($m['options'] as &$o)$o['id'].='_copy';unset($o);foreach($m['properties']['matrix_rows'] as &$r){$r['id'].='_copy';$r['response_key'].='_copy';}unset($r);$d['elements'][]=$m;cr_reject(function()use($d){D::validate($d);});});
cr_test('Matrix independent responses and required semantics unchanged after naming correction',function(){$d=cr_one('matrix');$d['elements'][0]['properties']['required']=true;cr_assert(count(A::errors($d,array()))===3);$answers=array();foreach($d['elements'][0]['properties']['matrix_rows'] as $i=>$r)$answers[$r['response_key']]=$d['elements'][0]['options'][$i]['id'];cr_assert(!A::errors($d,$answers));});
cr_test('VAS legacy absolute size normalizes to relative small normal large',function(){foreach(array(12=>'small',14=>'small',16=>'normal',24=>'normal',25=>'large',36=>'large') as $size=>$scale){$d=cr_one('vas');unset($d['elements'][0]['properties']['label_scale']);$d['elements'][0]['properties']['label_font_size']=$size;$n=D::validate($d);cr_assert($n['elements'][0]['properties']['label_scale']===$scale);}});
cr_test('VAS size enum validates and explicit relative scale takes precedence over legacy size',function(){$d=cr_one('vas');$d['elements'][0]['properties']['label_font_size']=36;$d['elements'][0]['properties']['label_scale']='small';cr_assert(D::validate($d)['elements'][0]['properties']['label_scale']==='small');foreach(array('giant',1,null) as $bad){$d['elements'][0]['properties']['label_scale']=$bad;cr_reject(function()use($d){D::validate($d);});}});
cr_test('VAS semantic position decimals finite bounded and independent of step',function(){$d=cr_one('vas');$d['elements'][0]['properties']['step']=2;$d['elements'][0]['properties']['label_settings'][1]['position']=25.13;D::validate($d);foreach(array(-1,101,INF,'25') as $bad){$d['elements'][0]['properties']['label_settings'][1]['position']=$bad;cr_reject(function()use($d){D::validate($d);});}});
cr_test('VAS untouched initial touched required showvalue and gradients stay unchanged',function(){$d=cr_one('vas');$p=&$d['elements'][0]['properties'];$p['required']=true;$p['show_value']=false;$p['gradient']='improvement-left';cr_assert(count(A::errors($d,array('R_vas'=>50)))===1);cr_assert(!A::errors($d,array('R_vas'=>50),array('R_vas'=>true)));});
cr_test('rich content still sanitized by backend and formatting images persist',function(){$d=cr_one('text');$p=&$d['elements'][0]['properties'];$p['label_html']='<p><b>B</b><i>I</i><u>U</u></p><ul><li>Item</li></ul><img src="https://example.test/a.png" alt="A"><script>bad()</script><iframe></iframe><a href="javascript:bad()" onclick="bad()">Link</a>';$n=D::validate($d);$html=$n['elements'][0]['properties']['label_html'];cr_assert(strpos($html,'<b>')!==false&&strpos($html,'<img')!==false);cr_assert(!preg_match('/<script|<iframe|onclick=|javascript:/i',$html));});
cr_test('corrected definition save load retains full data contract and native metadata',function()use(&$owned){$d=cr_fixture();$d['id']='AE_'.bin2hex(random_bytes(12));$owned[]=$d['id'];R::save($d,0);cr_assert(D::json(R::load($d['id'])['definition'])===D::json($d));$one=cr_one('vas');$mapped=M::map($one)->toArray();cr_assert(D::json($mapped['protocol_metadata']['native_definition'])===D::json($one));});
cr_test('Matrix Date Multiple URL still reject Engine mapping explicitly',function(){foreach(array('matrix','date','multiple_choice','url') as $t)cr_reject(function()use($t){M::map(cr_one($t));});});
}finally{wp_set_current_user(1);foreach($owned as $id)delete_option(R::PREFIX.$id);}
echo "$tests tests, $failures failures\n";exit($failures?1:0);
